export{ModalFamiliaCtrl};function ModalFamiliaCtrl($scope,$uibModalInstance,familiaSvc,tS,params){$scope.data={},"object"==typeof params&&params.idFamilia>0?($scope.tipoRegistro=2,$scope.data=Object.assign({},params)):$scope.tipoRegistro=1,$scope.getFamilyCode=function(){$scope.data.descripcion&&1===$scope.tipoRegistro&&($scope.data.siglas=$scope.data.descripcion.substring(0,3))},$scope.saveAndUpdate=function(){try{const tituloToastr=1===$scope.tipoRegistro?"Nuevo":"Actualizar";if(!$scope.data.descripcion)return void tS.toastr("warning","Ingrese la Descripción",tituloToastr);if(!$scope.data.siglas)return void tS.toastr("warning","Ingrese la Sigla",tituloToastr);showLoader(),$scope.data.idFamilia>0?familiaSvc.update($scope.data.idFamilia,$scope.data).then($scope.successReponse).catch(err=>{hideLoader(),console.log(err)}):familiaSvc.save($scope.data).then($scope.successReponse).catch(err=>{hideLoader(),console.log(err)})}catch(error){hideLoader(),console.log(error)}},$scope.successReponse=function(response){hideLoader(),"0"===response.code&&tS.toastr("warning",response.message,response.titleSms),"1"===response.code&&(tS.toastr("success",response.message,response.titleSms),$uibModalInstance.close(response))},$scope.closeModal=function(){$uibModalInstance.close()}}ModalFamiliaCtrl.$inject=["$scope","$uibModalInstance","familiaService","toastService","params"];